scripts.source:
dismiss-notifications
@toggle provider="display.mode" equals="mirror" display="screenshot-desk"
  @match
    extend-display display="screenshot-desk"
  @otherwise
    mirror-display display="screenshot-desk" source="screenshot-main"
@end

@toggle provider="display.mode" equals="mirror" display="screenshot-desk"
  @match
    extend-display display="screenshot-desk"
  @otherwise
    mirror-display display="screenshot-desk" source="screenshot-main"
@end
